import math


def evaluate(expr: str) -> int:
    # Tokenize the input string
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            j = i + 1
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif ch in "+-*/%^!()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch!r}")

    if not tokens:
        raise ValueError("Empty expression")

    # Precedence and associativity (True = right-associative)
    # '+' and '-': 1, '*', '/', '%': 2, unary '-': 3, '^': 4
    PREC = {
        "+": (1, False),
        "-": (1, False),
        "*": (2, False),
        "/": (2, False),
        "%": (2, False),
        "u-": (3, True),
        "^": (4, True),
    }

    values = []
    ops = []

    def apply_op(op: str) -> None:
        if op == "u-":
            if not values:
                raise ValueError("Malformed expression")
            values[-1] = -values[-1]
            return

        if len(values) < 2:
            raise ValueError("Malformed expression")
        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "/":
            if b == 0:
                raise ValueError("Division by zero")
            q = abs(a) // abs(b)
            values.append(-q if (a < 0) ^ (b < 0) else q)
        elif op == "%":
            if b == 0:
                raise ValueError("Modulo by zero")
            r = abs(a) % abs(b)
            values.append(-r if a < 0 else r)
        elif op == "^":
            if b < 0:
                raise ValueError("Negative exponent")
            values.append(a**b)

    def push_binary_op(op: str) -> None:
        prec, right_assoc = PREC[op]
        while ops and ops[-1] != "(":
            top_prec, _ = PREC[ops[-1]]
            if top_prec > prec or (top_prec == prec and not right_assoc):
                apply_op(ops.pop())
            else:
                break
        ops.append(op)

    expect_operand = True

    for tok in tokens:
        if expect_operand:
            if isinstance(tok, int):
                values.append(tok)
                expect_operand = False
            elif tok == "(":
                ops.append("(")
            elif tok == "-":
                ops.append("u-")
            else:
                raise ValueError(f"Unexpected token: {tok!r}")
        else:
            if tok == "!":
                if not values or values[-1] < 0:
                    raise ValueError("Invalid factorial operand")
                values[-1] = math.factorial(values[-1])
            elif tok == "(":
                # Implicit multiplication after a number, ')' or '!'
                push_binary_op("*")
                ops.append("(")
                expect_operand = True
            elif tok == ")":
                while ops and ops[-1] != "(":
                    apply_op(ops.pop())
                if not ops or ops[-1] != "(":
                    raise ValueError("Mismatched parentheses")
                ops.pop()
            elif isinstance(tok, str) and tok in "+-*/%^":
                push_binary_op(tok)
                expect_operand = True
            else:
                raise ValueError(f"Unexpected token: {tok!r}")

    if expect_operand:
        raise ValueError("Incomplete expression")

    while ops:
        op = ops.pop()
        if op == "(":
            raise ValueError("Mismatched parentheses")
        apply_op(op)

    if len(values) != 1:
        raise ValueError("Malformed expression")

    return values[0]
